package com.tracksphere.application.safety.dto;
import jakarta.validation.constraints.*; import java.time.Instant; import java.util.UUID;
public final class SafetyDtos { private SafetyDtos(){} public record GeofenceRequest(@NotBlank @Size(max=120) String name,@NotNull @DecimalMin("-90") @DecimalMax("90") Double latitude,@NotNull @DecimalMin("-180") @DecimalMax("180") Double longitude,@NotNull @Positive Double radiusMeters){} public record GeofenceResponse(UUID id,String name,double latitude,double longitude,double radiusMeters,boolean active){} public record SosRequest(@DecimalMin("-90") @DecimalMax("90") Double latitude,@DecimalMin("-180") @DecimalMax("180") Double longitude,@Size(max=500) String message){} public record SosResponse(UUID id,String employee,String status,Instant createdAt){} public record NotificationResponse(UUID id,String title,String message,String severity,Instant createdAt,Instant readAt){} public record AuditResponse(UUID id,UUID actorId,String action,String target,String details,Instant createdAt){} }
